	2491: {
		names: [{ nominative: "Saint Paul the Confessor, Bishop of Constantinople († 350)", short: "Saint Paul" }],
		biographies: [
			{
				id: "bulgakov",
				translator: "Archpriest Eugene Tarris",
				text: "<p> He was born in Thessalonica, and was the successor of St. Alexander. He was a “champion of Orthodoxy, like the Apostle Paul adorned with piety, with courage of soul and endurance in tribulation”. For his zealous refutation of “the evil opinions of the Arians” he “endured persecution and tribulation” and four times was removed from the patriarchal throne by Emperor Constantius, who was an Arian. Finally, St. Paul was banished to a prison in Cucusa, Armenia where he died as a martyr “for the Trinity without beginning and one in essence”. The Arians killed him, strangling him during the service with his omophorion in the year 350. In the year 381 his uncorrupted relics were transferred to Constantinople and in 1236 to Venice where they remain until today. </p>",
			},
		],
		info: [],
		refs: [],
		services: [
			{
				type: "2",
				hymns: [],
				sections: [
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "Through thy confession of the divine Faith the Church hath shown thee to be another Paul, * a zealot among her priests; * and Abel crieth out to the Lord with thee, * as doth the righteous blood of Zachariah. ** O venerable father, entreat Christ God, that we be given great mercy.",
								type: "1",
								tone: "3",
								translator: "Aleksandr Andreev",
							},
							{
								kind: "kontakion",
								text: "O Paul, who shone forth upon the earth like a star of heavenly splendor, * thou dost now enlighten the universal Church * for which thou didst suffer, laying down thy life. * And like that of Zachariah and Abel, ** thy blood crieth out to the Lord.",
								type: "1",
								tone: "2",
								translator: "Aleksandr Andreev",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
