	220201: {
		names: [
			{ nominative: "Venerable Theodore the Confessor, Abbot of the Studion († 826)", short: "Venerable Theodore" },
		],
		biographies: [
			{
				id: "bulgakov",
				translator: "Archpriest Eugene Tarris",
				text: "Born in Constantinople, he received his higher education and, having accepted monasticism, he was tonsured in their Saccudion monastery, committing his life to the high principle of good works. During the reign of the Emperors Constantine Copronymus and Leo the Armenian Saint Theodore suffered much as a venerator of icons and underwent imprisonment. In the reign of Irene he founded the Studite Monastery in Constantinople, for which he wrote the rule and in which he was the rector. The venerable Theodore put in the basis of the monastic organization the general rule of St. Basil the Great, for which he was given special respect and with which he knew to perfection, while yet a monk in the Saccudion monastery. Following these rules in his the personal life, he soon became rector, and tried to apply them to the structure of the whole monastery. Owing to the increase in the number of brothers, the venerable Theodore did not have enough time, nor the strength to enter into it himself and personally to keep the rules, that is why he set up the entire order of positions, to help him with the administration and management of the monastery. For the direction of these persons he wrote a manual in iambic verses, where he set forth the duties beginning with the abbot and ending with the least of the brethren. He died in 826 in the little place of Acritos. The Venerable Theodore left many compositions, letters, canons, and church stikhera. The Typikon is indebted to the Venerable Theodore for his significant additions, concerning the structure and cycle of the church services. For the Great Lenten services the Venerable Theodore structured the Three Ode Canon for Matins, and together with his own brother Joseph of Saloni_a was called the author of the Triodion.",
			},
		],
		info: [],
		refs: [],
		services: [
			{
				type: "1",
				hymns: [],
				sections: [
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "O instructor of Orthodoxy, teacher of piety and purity, * beacon for the whole world, divinely inspired adornment of monastics. * O most wise Theodore by thy doctrines thou hast illumined all. ** O harp of the Spirit, entreat Christ God that our souls be saved.",
								type: "1",
								tone: "0",
							},
							{
								kind: "kontakion",
								text: "Thine angelic life of fasting * thou didst adorn with the struggles of suffering, * O divinely blessed Theodore, * and thou hast been shown to abide with the angels. ** With them cease thou never to pray to Christ God for us all.",
								type: "1",
								tone: "2",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
	247901: {
		names: [
			{
				nominative: "Venerable Acepsimas, Hermit of Cyrrhus in Syria (4<sup>th</sup> C)",
				short: "Venerable Akepsimos",
			},
		],
		biographies: [
			{
				id: "bulgakov",
				translator: "Archpriest Eugene Tarris",
				text: "<p>He practiced asceticism as a hermit near Cyrrhus, Syria during the reign of Theodosius the Great. Ven. Acepsimas spent 60 years in a rather narrow cave, committed to fasting and continual prayer, and not seeing anybody, and died in peace.</p>",
			},
		],
		info: [],
		refs: [],
		services: [],
		hymns: [],
	},
	248801: {
		names: [
			{
				nominative: "Martyrs Galaction and his wife Epistimia, at Emesa (3<sup>rd</sup> C)",
				short: "Martyrs Galaction",
			},
		],
		biographies: [
			{
				id: "bulgakov",
				translator: "Archpriest Eugene Tarris",
				text: "<p> They suffered for Christ during the persecution of Decius in the city of Emesa, Phœnicia. St. Galaction, being a Christian, according to the will of his parents, was betrothed to the pagan Epistime. Having instructed her in the holy faith, St. Galaction convinced her to lead a virgin life, and was himself tonsured as a monk on Mount Publion near Sinai. During the persecution when he was seized for torture, St. Epistime voluntarily joined him to share with him the cup of suffering. After severe tortures both holy martyrs were beheaded. </p>",
			},
		],
		info: [],
		refs: [],
		services: [
			{
				type: "1",
				hymns: [],
				sections: [
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "Thy martyrs, O Lord, through their sufferings have received incorruptible crowns from Thee, our God. For having Thy strength, they despoiled their adversaries, and shattered the powerless audacity of demons. Through their intercessions, save Thou our souls!",
								type: "1",
								tone: "4",
								translator: "Aleksandr Andreev",
							},
							{
								kind: "kontakion",
								text: "Thou hast been counted among the ranks of the martyrs of Christ, having fought valiantly, thou brightly struggled, O glorious Galaction, with thine honourable wife and fellow sufferer, Epistime; pray ye unceasingly to the one God for us all.",
								type: "1",
								tone: "2",
								translator: "Aleksandr Andreev",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
